breathing.py:
"""Estimate breathing rate from a motion signal, or decline to."""

from dataclasses import dataclass

import numpy as np
from scipy.signal import butter, find_peaks, sosfiltfilt

MIN_BPM = 6.0
MAX_BPM = 42.0
SEARCH_BPM = (4.5, 46.0)  # wider than reported, so limits are not edge peaks
LIMIT_TOLERANCE = 0.5  # breaths/min allowed past the limits for estimation error
MIN_PERIODICITY = 0.5  # correlation between the signal and itself one breath later
FS = 10.0  # uniform resampling rate, Hz
MIN_SECONDS = 25.0
MIN_COVERAGE = 0.8
MAX_GAP = 1.0  # longest tolerated hole in tracking, seconds
MIN_CONFIDENCE = 0.8
MIN_RMS = 2e-4  # smallest usable motion, in shoulder widths
FADE_PERIODS, MIN_FADE_SECONDS = 0.9, 2.5  # length of the stretch checked for faded motion
FADE_RATIO = 0.4  # least motion in any such stretch, relative to the typical one
MAX_MIRRORING = 0.4  # how far the signal may be explained by background motion
MIN_LEAK, MAX_LEAK = 0.3, 0.5  # camera motion left in the signal: relative size, and match
MAX_CAMERA_RATIO = 3.0  # camera motion, relative to the signal, that cannot be removed well enough
MAX_HEAD_RATIO, MIN_HEAD_MATCH = 0.85, 0.7  # head motion, relative to the chest, that means rocking
MIN_SWAY_MATCH = 0.7  # how closely sideways motion must follow the signal to mean swaying
MIN_SIDE_MATCH = 0.85  # least agreement between the halves of the chest
# Breath counting, used when the rhythm is too uneven for the spectrum alone.
COUNT_CONFIDENCE = 0.6  # least spectral score
COUNT_AGREEMENT = 2.0  # breaths/min between peaks, troughs, and the spectrum
COUNT_TIMING = 0.2  # largest relative spread of breath lengths
COUNT_LENGTHS = (0.6, 1.5)  # shortest and longest breath, relative to the typical one
COUNT_DEPTH = 0.35  # largest relative spread of breath depths
MIN_BREATHS = 4
MAX_RATE_SPREAD = 4.0  # disagreement between window halves, breaths/min


@dataclass(frozen=True)
class Reading:
    """`bpm` is None whenever the data cannot be trusted.

    An unmeasured rate says nothing about whether the person is breathing.
    """

    bpm: float | None
    confidence: float  # heuristic 0-1 spectral score, not a probability
    reason: str

    @property
    def status(self) -> str:
        return "measured" if self.bpm is not None else "unable to assess"


def _decline(reason: str, confidence: float = 0.0) -> Reading:
    return Reading(None, confidence, reason)


def _peak(x: np.ndarray) -> tuple[float, float]:
    """Return (breaths/min, fraction of band power near the peak)."""
    n_fft = 4096
    x = x - x.mean()
    power = np.abs(np.fft.rfft(x * np.hanning(len(x)), n_fft)) ** 2
    bpm = np.fft.rfftfreq(n_fft, 1 / FS) * 60
    band = (bpm >= SEARCH_BPM[0]) & (bpm <= SEARCH_BPM[1])
    power, bpm = power[band], bpm[band]
    if power.sum() <= 0:
        return 0.0, 0.0
    k = int(power.argmax())
    if k in (0, len(power) - 1):  # edge maximum: drift or out-of-band motion
        return float(bpm[k]), 0.0
    a, b, c = power[k - 1 : k + 2]
    curve = a - 2 * b + c
    shift = 0.5 * (a - c) / curve if curve else 0.0
    rate = float(bpm[k] + shift * (bpm[1] - bpm[0]))
    half_width = 2 * 60 * FS / len(x)  # Hann main lobe
    # Breathing is not a pure sine, so its second harmonic counts too.
    near = (np.abs(bpm - rate) <= half_width) | (np.abs(bpm - 2 * rate) <= half_width)
    return rate, float(power[near].sum() / power.sum())


def _autocorrelation_rate(x: np.ndarray, rate: float) -> tuple[float, float]:
    """Return (breaths/min, correlation) at the best lag within 15% of `rate`.

    `x` must keep motion slower than the search band: when a harmonic is mistaken
    for the breathing rate, the slower true rhythm makes this correlation low.
    """
    period = 60 * FS / rate
    lags = np.arange(max(2, int(period * 0.85)), int(np.ceil(period * 1.15)) + 1)
    lags = lags[lags < len(x) - 2]
    if not len(lags):
        return 0.0, 0.0
    scores = np.array([np.corrcoef(x[:-k], x[k:])[0, 1] for k in lags])
    k = int(scores.argmax())
    lag = float(lags[k])
    if 0 < k < len(lags) - 1:
        a, b, c = scores[k - 1 : k + 2]
        curve = a - 2 * b + c
        lag += 0.5 * (a - c) / curve if curve else 0.0
    return 60 * FS / lag, float(scores[k])


def _faded(velocity: np.ndarray, rate: float) -> bool:
    """True if motion nearly vanished for about a breath, at any point.

    Without this, a window that is mostly old breathing keeps reporting a rate
    long after the motion has changed.
    """
    n = int(max(MIN_FADE_SECONDS, FADE_PERIODS * 60 / rate) * FS)
    total = np.concatenate(([0.0], np.cumsum(velocity**2)))
    rms = np.sqrt(np.maximum(total[n:] - total[:-n], 0) / n)
    return bool(rms.min() < FADE_RATIO * np.median(rms))


def _mirrors(signal: np.ndarray, background: np.ndarray) -> bool:
    """True if the signal looks like background motion turned upside down.

    Background motion is subtracted to cancel camera shake. Real shake also moves
    the chest, so nothing of it is left. A curtain or fan moves only the
    background, and subtracting it would invent a breathing signal.
    """
    if np.std(background) < 0.1 * np.std(signal):
        return False
    return bool(np.corrcoef(signal, background)[0, 1] < -MAX_MIRRORING)


def _leaks(signal: np.ndarray, background: np.ndarray) -> bool:
    """True if the signal follows the camera motion that was subtracted.

    On a faint background, camera motion is underestimated and only part of it is
    removed. What is left moves the same way, and can look like breathing.
    """
    if np.std(background) < MIN_LEAK * np.std(signal):
        return False
    if np.std(background) > MAX_CAMERA_RATIO * np.std(signal):
        return True
    return bool(np.corrcoef(signal, background)[0, 1] > MAX_LEAK)


def _rocks(signal: np.ndarray, head: np.ndarray) -> bool:
    """True if the head moves with the chest, and about as much.

    Breathing moves the chest more than the head. Rocking moves both.
    """
    if np.std(head) < MAX_HEAD_RATIO * np.std(signal):
        return False
    return bool(abs(np.corrcoef(signal, head)[0, 1]) > MIN_HEAD_MATCH)


def _splits(right: np.ndarray, left: np.ndarray) -> bool:
    """True unless both halves of the chest move together.

    Wind in clothing and moving shadows often pass across the chest. An injured chest
    can also move unevenly, and a person should look at that.
    """
    if min(np.std(right), np.std(left)) <= 0:
        return True
    return bool(np.corrcoef(right, left)[0, 1] < MIN_SIDE_MATCH)


def _sways(signal: np.ndarray, across: np.ndarray) -> bool:
    """True if the chest moves at least as much across the image, in step.

    Swaying is mostly sideways, but a little of it is always vertical too.
    """
    if np.std(across) < np.std(signal):
        return False
    return bool(abs(np.corrcoef(signal, across)[0, 1]) > MIN_SWAY_MATCH)


def _count(x: np.ndarray, rate: float) -> float | None:
    """Return breaths/min by counting, or None unless the breaths are alike."""
    swing = np.percentile(x, 90) - np.percentile(x, 10)
    peaks, found = find_peaks(x, prominence=0.35 * swing)
    troughs, _ = find_peaks(-x, prominence=0.35 * swing)
    rates = []
    for marks in (peaks, troughs):
        if len(marks) < MIN_BREATHS:
            return None
        lengths = np.diff(marks)
        if lengths.std() > COUNT_TIMING * lengths.mean():
            return None
        rates.append(60 * FS / lengths.mean())
    lengths, depths = np.diff(peaks), found["prominences"]
    low, high = COUNT_LENGTHS
    typical = np.median(lengths)
    if lengths.min() < low * typical or lengths.max() > high * typical:
        return None
    if depths.std() > COUNT_DEPTH * depths.mean() or lengths.sum() < 0.7 * len(x):
        return None
    counted = sum(rates) / 2
    if abs(rates[0] - rates[1]) > COUNT_AGREEMENT or abs(counted - rate) > COUNT_AGREEMENT:
        return None
    return float(counted)


def estimate(times, values, background=None, head=None, sideways=None, sides=None) -> Reading:
    """Estimate from timestamps (s) and displacement (shoulder widths).

    Use NaN for frames in which the chest could not be tracked. `background` is the
    background displacement already subtracted from `values`, and `head` the
    head displacement on the same scale, if known. `sideways` is the chest's
    displacement across the image.
    """
    t = np.asarray(times, float)
    x = np.asarray(values, float)
    if t.shape != x.shape or t.ndim != 1:
        raise ValueError("times and values must be 1-D and the same length")
    if len(t) < 2 or t[-1] - t[0] < MIN_SECONDS - 0.2:
        return _decline("need more data")
    if np.any(np.diff(t) <= 0):
        raise ValueError("times must be strictly increasing")

    good = np.isfinite(x)
    if good.mean() < MIN_COVERAGE:
        return _decline("chest not visible")
    tg, xg = t[good], x[good]
    edges = np.concatenate(([t[0]], tg, [t[-1]]))
    if np.diff(edges).max() > MAX_GAP:
        return _decline("tracking interrupted")

    grid = np.arange(tg[0], tg[-1], 1 / FS)
    y = np.interp(grid, tg, xg)
    y = y - np.polyval(np.polyfit(grid - grid[0], y, 1), grid - grid[0])

    def companion(series):
        if series is None:
            return None
        values_there = np.interp(grid, tg, np.asarray(series, float)[good])
        return sosfiltfilt(sos, values_there - values_there.mean())

    sos = butter(2, [SEARCH_BPM[0] / 60 * 0.8, SEARCH_BPM[1] / 60 * 1.2], "bandpass", fs=FS, output="sos")
    filtered = sosfiltfilt(sos, y)
    rms = float(np.sqrt(np.mean(filtered**2)))
    if rms < MIN_RMS:
        return _decline("signal too weak")
    # A lurch dwarfs normal breaths.
    if np.abs(filtered).max() > 5 * np.median(np.abs(filtered)) + 1e-12:
        return _decline("too much movement")

    behind, above, across = companion(background), companion(head), companion(sideways)
    if behind is not None and _mirrors(filtered, behind):
        return _decline("background moving")
    if behind is not None and _leaks(filtered, behind):
        return _decline("camera moving")
    if above is not None and _rocks(filtered, above):
        return _decline("whole body moving")

    if sides is not None:
        right, left = (companion(side) for side in zip(*sides))
        if _splits(right, left):
            return _decline("chest moving unevenly")
    if across is not None and _sways(filtered, across):
        return _decline("whole body moving")

    # Accumulated tracking error is a random walk, whose low-frequency power can
    # imitate slow breathing. Its velocity has a flat spectrum, so require a
    # clear rhythm in velocity as well as displacement.
    rate, score = _peak(filtered)
    velocity = np.gradient(filtered, 1 / FS)
    v_rate, v_score = _peak(velocity)
    score = min(1.0, max(0.0, min(score, v_score)))
    if score < COUNT_CONFIDENCE:
        return _decline("signal not rhythmic enough", score)
    if abs(rate - v_rate) > MAX_RATE_SPREAD:
        return _decline("rate not stable", score)
    if not MIN_BPM - LIMIT_TOLERANCE <= rate <= MAX_BPM + LIMIT_TOLERANCE:
        return _decline("rate outside measurable range", score)
    low = butter(2, SEARCH_BPM[1] / 60 * 1.2, "lowpass", fs=FS, output="sos")
    smooth = sosfiltfilt(low, y)
    if _faded(np.gradient(smooth, 1 / FS), rate):
        return _decline("motion faded", score)
    ac_rate, periodicity = _autocorrelation_rate(smooth, rate)
    if periodicity < MIN_PERIODICITY or abs(ac_rate - rate) > MAX_RATE_SPREAD:
        return _decline("methods disagree", score)
    mid = len(filtered) // 2
    first, _ = _peak(velocity[:mid])
    second, _ = _peak(velocity[mid:])
    steady = abs(first - second) <= MAX_RATE_SPREAD
    if score >= MIN_CONFIDENCE and steady:
        return Reading(rate, score, "ok")
    counted = _count(filtered, rate)
    if counted is not None and MIN_BPM - LIMIT_TOLERANCE <= counted <= MAX_BPM + LIMIT_TOLERANCE:
        return Reading(counted, score, "ok")
    return _decline("rate not stable" if score >= MIN_CONFIDENCE else "signal not rhythmic enough", score)

decision.py:
"""Decide whether to report, wait, move, or ask for human help.

Safety rule: there is no status meaning "not breathing". If breathing cannot be
measured and the person does not respond, the only outcome is "unable to assess".
"""

import math
from dataclasses import dataclass
from enum import Enum

from .breathing import Reading


class Action(str, Enum):
    REPORT = "report"
    WAIT = "wait"
    MOVE = "move"
    GET_HELP = "get help"


class Status(str, Enum):
    MEASURED = "breathing measured"
    RESPONDED = "responded"
    UNABLE = "unable to assess"


# Problems that a different view may solve. Anything else is worth waiting out first.
VIEW_PROBLEMS = {
    "chest not visible",
    "not enough chest detail",
    "cannot check camera motion",
    "signal too weak",
    "background moving",
}


@dataclass(frozen=True)
class Limits:
    confirm_seconds: float = 3.0  # a rate must hold this long before it is reported
    max_rate_change: float = 4.0  # breaths/min, while confirming
    view_problem_seconds: float = 5.0  # patience for a bad view
    view_seconds: float = 60.0  # longest stay at one viewpoint
    total_seconds: float = 180.0  # longest time spent on one person


@dataclass(frozen=True)
class Decision:
    action: Action
    status: Status
    reason: str
    bpm: float | None = None

    completed_at_s: float | None = None

    @property
    def final(self) -> bool:
        return self.action in (Action.REPORT, Action.GET_HELP)


class Assessor:
    """State machine for one person. Create a new one to reassess.

    After a MOVE decision, call `arrived` or `move_failed`. The caller must also
    discard signal collected while moving.

    With `ask_first`, the assessor sets `wants_ask` once at each view before leaving
    it or giving up, and waits while `update` is told that asking is under way. The
    total time limit still applies.
    """

    def __init__(self, t: float, extra_views: int, limits: Limits = Limits(), ask_first: bool = False):
        if extra_views < 0:
            raise ValueError("extra_views cannot be negative")
        self.limits = limits
        self.views_left = extra_views
        self.ask_first = ask_first
        self.wants_ask = False
        self._asked = False
        self.decision = Decision(Action.WAIT, Status.UNABLE, "starting")
        self._start = self._view_start = self._now = self._check(t)
        self._problem_since = None
        self._confirm_since = None
        self._confirm_bpm = None

    @staticmethod
    def _check(t):
        if not math.isfinite(t):
            raise ValueError("time must be finite")
        return t

    def _tick(self, t):
        if self._check(t) < self._now:
            raise ValueError("time cannot go backwards")
        self._now = t

    def _set(self, action, reason, status=Status.UNABLE, bpm=None):
        completed = self._now if action in (Action.REPORT, Action.GET_HELP) else None
        self.decision = Decision(action, status, reason, bpm, completed)
        return self.decision

    def _leave(self, reason, asking):
        if asking:
            return self._set(Action.WAIT, "waiting for a response")
        if self.ask_first and not self._asked:
            self._asked = self.wants_ask = True
            return self._set(Action.WAIT, "asking for a response")
        return self._next_view(reason)

    def _next_view(self, reason):
        if self.views_left:
            self.views_left -= 1
            return self._set(Action.MOVE, reason)
        return self._set(Action.GET_HELP, f"{reason}; no views left")

    def _begin_view(self):
        self._view_start = self._now
        self._asked = False
        self._problem_since = self._confirm_since = self._confirm_bpm = None

    def arrived(self, t: float) -> Decision:
        if self.decision.action is not Action.MOVE:
            raise ValueError("not moving")
        self._tick(t)
        self._begin_view()
        return self._set(Action.WAIT, "starting new view")

    def move_failed(self, t: float) -> Decision:
        if self.decision.action is not Action.MOVE:
            raise ValueError("not moving")
        self._tick(t)
        return self._next_view("could not reach view")

    def update(self, t: float, reading: Reading, responded: bool = False, asking: bool = False) -> Decision:
        """`responded=False` means no response was seen, which proves nothing."""
        if self.decision.final:
            return self.decision
        self._tick(t)
        self.wants_ask = False
        if asking:
            self._asked = True
        if responded:
            return self._set(Action.REPORT, "response seen", Status.RESPONDED)
        moving = self.decision.action is Action.MOVE
        if not moving and self._confirmed(reading):
            return self._set(Action.REPORT, "rate confirmed", Status.MEASURED, reading.bpm)
        if t - self._start >= self.limits.total_seconds:
            return self._set(Action.GET_HELP, "time limit reached")
        if moving:
            return self.decision

        if reading.bpm is not None:
            self._problem_since = None
            reason = "confirming rate"
        elif reading.reason in VIEW_PROBLEMS:
            reason = reading.reason
            if self._problem_since is None:
                self._problem_since = t
            if t - self._problem_since >= self.limits.view_problem_seconds:
                return self._leave(reason, asking)
        else:
            self._problem_since = None
            reason = reading.reason
        if t - self._view_start >= self.limits.view_seconds:
            return self._leave(reason, asking)
        return self._set(Action.WAIT, reason)

    def _confirmed(self, reading):
        bpm = reading.bpm
        if bpm is None or not math.isfinite(bpm):
            self._confirm_since = self._confirm_bpm = None
            return False
        if self._confirm_bpm is None or abs(bpm - self._confirm_bpm) > self.limits.max_rate_change:
            self._confirm_since, self._confirm_bpm = self._now, bpm
            return False
        return self._now - self._confirm_since >= self.limits.confirm_seconds

response.py:
"""Ask a person to raise a hand, and watch for it.

A response is only ever positive evidence. Seeing none proves nothing: the person
may be deaf, trapped, hurt, out of view, or not understand the language.
"""

import math
import shutil
import subprocess
from dataclasses import dataclass

import numpy as np

PROMPT = "If you can hear me, please raise one hand."
MIN_VISIBILITY = 0.7
RAISED = 0.1  # wrist past the shoulder line toward the head, in shoulder widths
LOWERED = -0.2
MIN_SIDE = 0.4  # shoulder widths from the body midline; a hand at the face is closer
DOWN_SECONDS = 0.5  # a hand must first be seen down for this long
HOLD_SECONDS = 0.6  # and then be held up for this long
LISTEN_SECONDS = 10.0
MAX_GAP = 1.0  # seconds without a view of the arm before its history is dropped
LYING_TILT = 40.0  # degrees between the torso and image-down
MIN_TORSO = 0.6  # torso length needed to trust its direction, in shoulder widths
TORSO_RATIO = 1.5  # typical torso length, in shoulder widths
MIN_LIFT = 1.1  # wrist above its own shoulder, for a hand raised from lying down
RESTING_LIFT = 0.3
PAST_HEAD = 1.1  # toward the head, for a hand raised along the ground
MAX_JUMP = 0.5  # body shift between frames, in shoulder widths: maybe someone else


@dataclass(frozen=True)
class Body:
    """Shoulder center and width in pixels, and each wrist's height: toward the head, or off the
    ground if lying down."""

    center: tuple[float, float]
    width: float
    left: float | None  # shoulder widths; None if the wrist cannot be seen
    right: float | None


def lying_axes(points):
    """Return (shoulder center, unit vector toward the hips, scale), or None if upright.

    Seen from the side, a lying person's shoulders overlap, so the torso's length
    sets the scale when it implies wider shoulders than can be seen.
    """
    if not (np.abs(points) < 1e5).all():  # also rejects NaN
        return None
    across = points[0] - points[1]
    width = float(np.linalg.norm(across))
    center = (points[0] + points[1]) / 2
    torso = (points[2] + points[3]) / 2 - center
    length = float(np.linalg.norm(torso))
    if length < MIN_TORSO * width or length < 1:
        return None
    down = torso / length
    if np.degrees(np.arccos(np.clip(down[1], -1, 1))) < LYING_TILT:
        return None
    return center, down, max(width, length / TORSO_RATIO)


def _lying_body(points, visibility, size):
    """As `body_from_landmarks`, for a person lying across the image, or None.

    They may raise a hand past the head, or off the ground. Motion along the body is
    left out of the second, so an arm resting beside the body is never "raised".
    """
    if not min(visibility[i] for i in (23, 24)) >= MIN_VISIBILITY:
        return None
    axes = lying_axes(np.array([points[i] for i in (11, 12, 23, 24)], float))
    if axes is None:
        return None
    center, down, scale = axes
    nose = np.asarray(points[0], float) - center
    if scale < 60 or not -(nose @ down) >= 0.15 * scale:
        return None
    side = np.array([-down[1], down[0]])
    side = side if side[1] < 0 else -side  # image-up, across the body

    def height(wrist, shoulder):
        x, y = points[wrist]
        if not (math.isfinite(x) and math.isfinite(y)):
            return None
        point = np.array([x, y], float)
        inside = 0 <= x < size[0] and 0 <= y < size[1]
        value = -float((point - center) @ down) / scale
        lift = float((point - np.asarray(points[shoulder], float)) @ side) / scale
        if 0 < value < PAST_HEAD:
            value = 0.0  # perhaps touching the face, which rises off the ground too
        if lift >= MIN_LIFT:
            value = max(value, lift)
        elif lift > RESTING_LIFT:
            value = max(value, 0.0)  # neither raised nor down
        if inside:
            return value if visibility[wrist] >= MIN_VISIBILITY else None
        return value if value <= LOWERED else None

    return Body((float(center[0]), float(center[1])), scale, height(15, 11), height(16, 12))


def body_from_landmarks(points, visibility, size):
    """`points` and `visibility` follow MediaPipe's 33 pose landmarks, in pixels.
    `size` is the frame (width, height).

    Height is measured from the shoulders toward the nose, so it does not depend on
    the person being upright. Returns None if the direction cannot be measured.
    """
    if not min(visibility[i] for i in (0, 11, 12)) >= MIN_VISIBILITY:
        return None
    lying = _lying_body(points, visibility, size)
    if lying is not None:
        return lying
    nose, left, right = (np.asarray(points[i], float) for i in (0, 11, 12))
    center, across = (left + right) / 2, left - right
    width = float(np.linalg.norm(across))
    if not (width >= 60 and np.isfinite([*nose, *center]).all()):
        return None
    up = np.array([-across[1], across[0]]) / width
    toward_head = float((nose - center) @ up)
    if abs(toward_head) < 0.15 * width:
        return None
    up = up * math.copysign(1, toward_head)

    def height(i):
        x, y = points[i]
        if not (math.isfinite(x) and math.isfinite(y)):
            return None
        offset = np.array([x, y], float) - center
        value = float(offset @ up) / width
        if value > 0 and abs(float(offset @ across)) / width**2 < MIN_SIDE:
            value = 0.0  # near the face or chest: neither raised nor down
        inside = 0 <= x < size[0] and 0 <= y < size[1]
        if inside:
            return value if visibility[i] >= MIN_VISIBILITY else None
        # A resting hand is often just out of frame. The model's guess is enough to
        # call it down, but a raised hand must really be seen.
        return value if value <= LOWERED else None

    return Body((float(center[0]), float(center[1])), width, height(15), height(16))


class _Arm:
    """Looks for one hand seen down, then raised and held."""

    def __init__(self):
        self.reset()

    def reset(self):
        self._last = self._down_since = self._up_since = None
        self._was_down = False
        self.high = False  # seen raised, and not seen lowered since

    @property
    def raised_since(self):
        return self._up_since

    def update(self, t, height):
        """Return how long the hand has been held up after being down."""
        if self._last is not None and t - self._last > MAX_GAP:
            self.reset()
        if height is None:
            self._up_since = self._down_since = None  # a hold must be seen throughout
            return 0.0
        self._last = t
        if height >= RAISED:
            self.high = True
            self._down_since = None
            if not self._was_down:
                return 0.0
            if self._up_since is None:
                self._up_since = t
            return t - self._up_since
        self._up_since = None
        if height <= LOWERED:
            self.high = False
            if self._down_since is None:
                self._down_since = t
            if t - self._down_since >= DOWN_SECONDS:
                self._was_down = True
        else:
            self._down_since = None
        return 0.0


class Speaker:
    """Speaks with a voice already on this computer. Nothing is sent anywhere."""

    TIMEOUT = 15.0
    READ_SECONDS = 4.0  # time to read the screen if there is no voice

    def __init__(self):
        self._command = next((c for c in ("say", "espeak-ng", "espeak") if shutil.which(c)), None)
        self._process = self._start = None
        self.failed = False

    def start(self, t):
        self.stop()
        self.failed, self._start = self._command is None, t
        if self._command:
            try:
                self._process = subprocess.Popen(
                    [self._command, PROMPT],
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
            except OSError:
                self.failed = True

    def finished(self, t):
        if self._process is not None:
            code = self._process.poll()
            if code is None:
                if t - self._start < self.TIMEOUT:
                    return False
                self.stop()
                self.failed = True
            elif code:
                self.failed = True
            self._process = None
        return not self.failed or t - self._start >= self.READ_SECONDS

    def stop(self):
        if self._process is not None and self._process.poll() is None:
            self._process.terminate()
            try:
                self._process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                self._process.kill()
                self._process.wait()
        self._process = None


class ResponseCheck:
    """One prompt at a time: idle, speaking, watching, then done."""

    def __init__(self, speaker):
        self.speaker = speaker
        self.state = "idle"
        self.outcome = None  # "response" or "none seen", for the latest prompt
        self._seen = False
        self._arms = (_Arm(), _Arm())
        self._body = self._watch_start = self._asked_at = None

    @property
    def active(self):
        return self.state in ("speaking", "watching")

    def ask(self, t):
        if not self.active:
            self.state, self._asked_at, self.outcome = "speaking", t, None
            self._seen = False
            for arm in self._arms:
                if arm.high:  # already up, even if hidden right now: needs a fresh lower
                    arm.reset()
            self.speaker.start(t)

    def cancel(self):
        self.speaker.stop()
        self.state, self.outcome = "idle", None
        self._body = None
        for arm in self._arms:
            arm.reset()

    def update(self, t, body):
        """Call on every frame, even when idle. Return True once, if a response is seen."""
        if body is not None:
            old = self._body
            if old is not None and math.dist(body.center, old.center) > MAX_JUMP * old.width:
                self._seen = False
                for arm in self._arms:
                    arm.reset()
            self._body = body
        heights = (None, None) if body is None else (body.left, body.right)
        held = [arm.update(t, h) for arm, h in zip(self._arms, heights)]

        if self.active:
            for duration, arm in zip(held, self._arms):
                if duration >= HOLD_SECONDS and arm.raised_since >= self._asked_at:
                    self._seen = True
        if self.state == "speaking" and self.speaker.finished(t):
            self.state, self._watch_start = "watching", t
        if self.state != "watching":
            return False
        # The hand must be raised after the request, or while it was being made.
        if self._seen:
            self.state, self.outcome = "done", "response"
            return True
        if t - self._watch_start >= LISTEN_SECONDS:
            self.state, self.outcome = "done", "none seen"
        return False

    def message(self):
        """Return (headline, detail) while a prompt is running, else None."""
        if not self.active:
            return None
        how = "Voice unavailable: showing text only" if self.speaker.failed else "Asked out loud"
        if self.state == "speaking":
            return f"ASKING: {PROMPT}", how if self.speaker.failed else "Speaking now"
        return "WATCHING for a raised hand", f"{how}. Start with hands down, then raise one and hold."
